//! The dart pubspec reader against PyYAML 6.0.3 (`CSafeLoader`, as pre-commit 4.6.2 loads `pubspec.yaml`):
//! `testdata/group2/pubspec/vectors.jsonl`, generated by `gen_vectors.py` in the same directory with the oracle venv.
//!
//! Rules: an input PyYAML refuses is refused; an input PyYAML reads is read identically or refused (the reader is a
//! subset: never a different command, never a command pre-commit would not run); the realistic pubspecs (`accept`)
//! are read identically. `SNP_PUBSPEC_VECTORS` points the test at another (e.g. larger, locally generated) file.

use std::path::PathBuf;

use serde_json::Value;
use snp_lang::langs::dart::{Executables, pubspec_executables};

/// The vector file.
fn vectors() -> PathBuf {
    #[expect(
        clippy::disallowed_methods,
        reason = "test switch naming another vector file"
    )]
    let over = std::env::var_os("SNP_PUBSPEC_VECTORS");
    over.map_or_else(
        || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("testdata/group2/pubspec/vectors.jsonl"),
        PathBuf::from,
    )
}

/// What PyYAML made of a vector.
enum Want {
    /// `yaml_load` raised, or the document is not a mapping: pre-commit crashes.
    Crash,
    /// The loop's input.
    Is(Executables),
}

/// The oracle outcome.
fn want_of(want: &Value) -> Want {
    let obj = want.as_object().unwrap();
    let ty = |v: &Value| -> &'static str {
        match v.as_str().unwrap() {
            "int" => "int",
            "bool" => "bool",
            "float" => "float",
            "NoneType" => "NoneType",
            "list" => "list",
            "dict" => "dict",
            other => Box::leak(other.to_owned().into_boxed_str()),
        }
    };
    if obj.contains_key("error") || obj.contains_key("notmap") {
        return Want::Crash;
    }
    if obj.contains_key("empty") {
        return Want::Is(Executables::EmptyDocument);
    }
    if obj.contains_key("missing") {
        return Want::Is(Executables::Missing);
    }
    if obj.contains_key("null") {
        return Want::Is(Executables::Null);
    }
    if let Some(t) = obj.get("notiter") {
        return Want::Is(Executables::NotIterable(ty(t)));
    }
    let names: Vec<String> = obj["names"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| n.as_str().unwrap().to_owned())
        .collect();
    Want::Is(match obj.get("nonstr") {
        Some(t) if !t.is_null() => Executables::NamesThenNonStr(names, ty(t)),
        _ => Executables::Names(names),
    })
}

#[test]
fn lang_dart_pubspec_matches_pyyaml_vectors() {
    let text = std::fs::read_to_string(vectors()).unwrap();
    let (mut total, mut refused_valid) = (0_usize, 0_usize);
    let mut failures = Vec::new();
    for line in text.lines() {
        let rec: Value = serde_json::from_str(line).unwrap();
        let src = rec["src"].as_str().unwrap();
        let accept = rec["accept"].as_bool().unwrap();
        let want = want_of(&rec["want"]);
        let got = pubspec_executables(src);
        total += 1;
        match (&want, &got) {
            (Want::Crash, Err(_)) => {}
            (Want::Is(w), Ok(g)) if w == g => {}
            (Want::Is(_), Err(e)) if !accept => {
                refused_valid += 1;
                #[expect(
                    clippy::disallowed_methods,
                    reason = "test switch listing the refusals"
                )]
                let show = std::env::var_os("SNP_PUBSPEC_SHOW_REFUSED").is_some();
                if show {
                    eprintln!("refused {src:?}: {e}");
                }
            }
            _ => failures.push(format!(
                "{src:?}\n  pyyaml: {}\n  snp:    {got:?}",
                rec["want"]
            )),
        }
    }
    assert!(total > 1000, "{total} vectors");
    assert!(
        failures.is_empty(),
        "{} of {total} vectors disagree:\n{}",
        failures.len(),
        failures.join("\n")
    );
    eprintln!("{total} vectors, {refused_valid} valid inputs refused by the subset reader");
    // The subset may refuse valid YAML, but not most of it.
    assert!(
        refused_valid * 4 < total,
        "{refused_valid} of {total} valid inputs refused"
    );
}

#[test]
fn lang_dart_pubspec_reader_is_total_on_vector_mutations() {
    // Every prefix and single-character deletion of every vector: no panic.
    let text = std::fs::read_to_string(vectors()).unwrap();
    for line in text.lines().take(400) {
        let rec: Value = serde_json::from_str(line).unwrap();
        let src: Vec<char> = rec["src"].as_str().unwrap().chars().collect();
        for cut in 0..src.len() {
            let prefix: String = src[..cut].iter().collect();
            drop(pubspec_executables(&prefix));
            let deleted: String = src[..cut].iter().chain(&src[cut + 1..]).collect();
            drop(pubspec_executables(&deleted));
        }
    }
}

#[test]
fn lang_dart_pubspec_deep_nesting_fits_a_small_stack() {
    // The fuzzing invariant (256 KiB thread stacks): nesting is bounded, deeper documents are refused.
    let spaces = |n: usize| -> String { std::iter::repeat_n(' ', n).collect() };
    let times = |t: &str, n: usize| -> String { std::iter::repeat_n(t, n).collect() };
    let mut inputs = Vec::new();
    for depth in [10_usize, 63, 64, 65, 200, 5000] {
        let mut map = String::from("executables:\n  a:\n");
        let mut seq = String::from("executables:\n  a:\n");
        for d in 0..depth {
            map.push_str(&spaces(d + 4));
            map.push_str("k:\n");
            seq.push_str(&spaces(d + 4));
            seq.push_str("-\n");
        }
        inputs.push(map);
        inputs.push(seq);
        inputs.push(format!(
            "executables: {}{}\n",
            times("[", depth),
            times("]", depth)
        ));
        inputs.push(format!(
            "executables: {}a{}\n",
            times("{a: ", depth),
            times("}", depth)
        ));
        let compact: String = (0..depth).map(|d| spaces(d * 2) + "- ").collect();
        inputs.push(format!("executables:\n{compact}a\n"));
    }
    let worker = std::thread::Builder::new()
        .stack_size(256 * 1024)
        .spawn(move || {
            inputs
                .iter()
                .map(|i| pubspec_executables(i).is_ok())
                .collect::<Vec<_>>()
        })
        .unwrap();
    let ok = worker.join().unwrap();
    // Shallow documents are read, the deepest refused.
    assert!(ok[0] && ok[1] && ok[2] && ok[3]);
    assert!(!ok[ok.len() - 5] && !ok[ok.len() - 4] && !ok[ok.len() - 3] && !ok[ok.len() - 2]);
}
